<script setup lang="ts">
import {computed,reactive,ref} from 'vue';
import {FileSpreadsheet,PackagePlus,CheckCircle2,ArrowDownToLine,Archive,ArchiveRestore} from '@lucide/vue';
import DialogShell from './DialogShell.vue';
import ReceiptEditor from './ReceiptEditor.vue';
import {cleanProductName,productName} from './productName';
import {api} from './api';
import {allocateReceiptSlots,boxCategories} from './receiptAllocation';
import type {State,Purchase} from './types';
const props=defineProps<{state:State;writable:boolean}>();
const emit=defineEmits<{changed:[]}>();
interface OrderLine {source_row:number;supplier_code:string;name:string;brand:string;description:string;package:string;category:string;value:string;specs:Record<string,string>;quantity:number|string;shipped:number|string|null;unit_price:string;reuse_id?:string|null;errors:string[];warnings:string[]}
interface OrderPreview {update_existing?:boolean;expected_revision?:string;retained?:number;order_id:string;filename:string;sheet?:string;lines:OrderLine[];warnings?:string[];errors:number;total_quantity:number;already_imported:boolean}
const modal=ref(''),busy=ref(false),error=ref(''),message=ref(''),order=ref<OrderPreview|null>(null),signature=ref('');
const categoryOptions=['电阻','电容','电感','二极管','三极管','MOS管','芯片','MCU','连接器','开关','模块','其他'];
const specKeys=['精度','功率','耐压','介质','额定电流'];
async function task(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
function payload(){return {update_existing:order.value?.update_existing,expected_revision:order.value?.expected_revision,order_id:order.value?.order_id,filename:order.value?.filename,lines:order.value?.lines};}
const ready=computed(()=>!!order.value&&!order.value.errors&&(!order.value.already_imported||order.value.update_existing)&&signature.value===JSON.stringify(payload()));
async function parse(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await task(async()=>{const form=new FormData();form.append('file',file);order.value=await api<OrderPreview>('/purchases/import/parse','POST',form);signature.value=JSON.stringify(payload());modal.value='order';message.value='';});input.value='';}
async function preview(){await task(async()=>{const result=await api<OrderPreview>('/purchases/import/preview','POST',payload());order.value={...order.value,...result};signature.value=JSON.stringify(payload());});}
async function openOrder(id:string){await task(async()=>{order.value=await api<OrderPreview>('/purchases/orders/'+encodeURIComponent(id));signature.value=JSON.stringify(payload());modal.value='order';});}
async function commit(){await task(async()=>{const updating=order.value?.update_existing;const result=await api<{count:number;order_id:string;added?:number}>('/purchases/import/commit','POST',payload());modal.value='';message.value=updating?`订单 ${result.order_id} 已更新 ${result.count} 项，原验收和库存保留；新增 ${result.added||0} 项待验收。`:`订单 ${result.order_id} 已导入 ${result.count} 项，等待实物验收；库存尚未增加。`;emit('changed');});}
function cell(row:number,col:number){return String.fromCharCode(65+row)+(col+1);}
const allSlots=computed(()=>props.state.boxes.flatMap(b=>b.slots.map(s=>({...s,label:`${b.code} / ${cell(s.row_no,s.col_no)}`}))));
function stockAt(id:string){return props.state.parts.flatMap(p=>p.locations).find(s=>s.slot_id===id);}
function slotsFor(partId:string){return allSlots.value.filter(s=>!stockAt(s.id)||stockAt(s.id)?.part_id===partId);}
const manualKind=ref('new'),manual=reactive({part_id:'',slot_id:'',quantity:1,note:'',name:'',category:'电阻',package:'0603',value:'',supplier_code:'',specs:{} as Record<string,string>});
const manualSlots=computed(()=>slotsFor(manualKind.value==='new'?'':manual.part_id));
function openManual(){Object.assign(manual,{part_id:'',slot_id:'',quantity:1,note:'',name:'',category:'电阻',package:'0603',value:'',supplier_code:'',specs:{}});manualKind.value='new';error.value='';modal.value='manual';}
async function manualSave(){await task(async()=>{const specs=Object.fromEntries(Object.entries(manual.specs).filter(([,v])=>v.trim()));await api('/intake/manual','POST',{part_id:manualKind.value==='existing'?manual.part_id:null,part:{...manual,specs},slot_id:manual.slot_id,quantity:manual.quantity,note:manual.note});modal.value='';message.value='手动入库完成，器件档案、库存和流水已保存。';emit('changed');});}
interface ReceiptRow {purchase:Purchase;selected:boolean;slot_id:string;quantity:number}
const receiptRows=ref<ReceiptRow[]>([]),allocationBox=ref(''),receiptTitle=ref('');
const allocationMessage=ref(''),allocationReasons=ref<Record<string,string>>({});
const selectedReceipts=computed(()=>receiptRows.value.filter(r=>r.selected));
function openReceive(orderId=''){receiptRows.value=props.state.purchases.filter(p=>['ordered','partial'].includes(p.status)&&(!orderId||p.order_id===orderId)).map(p=>({purchase:p,selected:false,slot_id:'',quantity:Math.max(0,(p.source_shipped??p.quantity)-p.received)}));allocationBox.value='';allocationMessage.value='';allocationReasons.value={};receiptTitle.value=orderId||'全部待验收采购';error.value='';modal.value='receipt';}
function allocate(){
 error.value='';
 const result=allocateReceiptSlots(props.state.boxes,props.state.parts,receiptRows.value,allocationBox.value);
 for(const row of selectedReceipts.value){const slot=result.assignments[row.purchase.id];if(slot)row.slot_id=slot;}
 allocationReasons.value=Object.fromEntries(result.unassigned.map(r=>[r.id,r.reason]));
 allocationMessage.value=`本次分配 ${Object.keys(result.assignments).length} 项，${result.unassigned.length?'仍有 '+result.unassigned.length+' 项待手动处理':'所选项均已分配位置'}。请核对后确认验收入库。`;
}


const receiptsReady=computed(()=>selectedReceipts.value.length>0&&selectedReceipts.value.every(r=>r.slot_id&&Number.isInteger(r.quantity)&&r.quantity>0&&r.quantity<=r.purchase.quantity-r.purchase.received));
async function receive(){await task(async()=>{const result=await api<{count:number;quantity:number}>('/purchases/receive-batch','POST',{items:selectedReceipts.value.map(r=>({id:r.purchase.id,slot_id:r.slot_id,quantity:r.quantity}))});modal.value='';message.value=`验收完成：${result.count} 项、${result.quantity} 个已入库。`;emit('changed');});}
function orderPurchases(id:string){return props.state.purchases.filter(p=>p.order_id===id);}
function orderPending(id:string){return orderPurchases(id).filter(p=>['ordered','partial'].includes(p.status));}
const orderFilter=ref<'current'|'archived'>('current');
const currentOrders=computed(()=>(props.state.purchase_orders||[]).filter(o=>!o.archived));
const archivedOrders=computed(()=>(props.state.purchase_orders||[]).filter(o=>o.archived));
const visibleOrders=computed(()=>orderFilter.value==='archived'?archivedOrders.value:currentOrders.value);
function canArchiveOrder(id:string){const purchases=orderPurchases(id);return purchases.length>0&&purchases.every(p=>['received','cancelled'].includes(p.status));}
async function setArchived(id:string,archived:boolean){await task(async()=>{await api('/purchases/orders/'+encodeURIComponent(id)+'/archive','PUT',{archived});message.value=archived?'订单已归档，可在「已归档」查看和恢复。':'订单已恢复到「当前订单」。';emit('changed');});}
const correctionIds=ref<string[]|null>(null);
function openCorrection(ids:string[]){correctionIds.value=ids;}
defineExpose({openCorrection});
function corrected(){message.value='验收修改已保存，库存按差额同步，原流水保留。';emit('changed');}
</script>
<template>
 <div class="intake-actions"><div><strong>订单到手，直接导入；零散物料，手动入库。</strong><p class="subtle">采购计划用于记录待买器件。已有立创订单可自动建档，实物收到后再验收。</p></div><div v-if="writable" class="row"><label class="button secondary"><FileSpreadsheet :size="16"/>导入立创订单<input type="file" hidden accept=".xls,.xlsx,.csv,.tsv" :disabled="busy" @change="parse"></label><button class="primary" @click="openManual"><PackagePlus :size="16"/>手动入库</button><button class="secondary" :disabled="!state.purchases.some(p=>['ordered','partial'].includes(p.status))" @click="openReceive()"><ArrowDownToLine :size="16"/>批量验收</button></div></div>
 <div v-if="message" class="callout" role="status"><CheckCircle2 :size="15"/> {{message}}</div><div v-if="error&&!modal" class="error-banner" role="alert">{{error}}</div><p v-if="busy&&!modal" class="subtle" role="status">正在解析订单…</p>
<section v-if="state.purchase_orders?.length" class="orders-section" aria-label="采购订单"><div class="orders-toolbar"><strong>采购订单</strong><div class="segmented" role="group" aria-label="订单归档筛选"><button :class="{active:orderFilter==='current'}" :aria-pressed="orderFilter==='current'" @click="orderFilter='current'">当前订单 {{currentOrders.length}}</button><button :class="{active:orderFilter==='archived'}" :aria-pressed="orderFilter==='archived'" @click="orderFilter='archived'">已归档 {{archivedOrders.length}}</button></div></div>
 <div class="purchase-orders"><article v-for="o in visibleOrders" :key="o.order_id"><div><span class="eyebrow">LCSC ORDER</span><span v-if="o.archived" class="badge neutral order-archive-badge">已归档</span><h3>{{o.order_id}}</h3><p class="subtle">{{orderPurchases(o.order_id).length}} 项 · {{orderPurchases(o.order_id).reduce((n,p)=>n+p.received,0)}} / {{orderPurchases(o.order_id).reduce((n,p)=>n+p.quantity,0)}} 个已入库</p></div><div v-if="writable" class="order-actions"><button class="secondary" :disabled="busy" @click="openOrder(o.order_id)">编辑订单</button><button v-if="orderPurchases(o.order_id).some(p=>p.received>0)" class="secondary" :disabled="busy" @click="openCorrection(orderPurchases(o.order_id).filter(p=>['ordered','partial','received'].includes(p.status)).map(p=>p.id))">修改验收</button><button class="secondary" :disabled="busy||!orderPending(o.order_id).length" @click="openReceive(o.order_id)">{{orderPending(o.order_id).length?'验收此订单':'已完成验收'}}</button><button v-if="o.archived" class="secondary" :disabled="busy" @click="setArchived(o.order_id,false)"><ArchiveRestore :size="14"/>恢复订单</button><button v-else class="text-button" :disabled="busy||!canArchiveOrder(o.order_id)" :title="canArchiveOrder(o.order_id)?'收进历史列表，保留采购记录和库存':'请先完成验收或取消剩余采购项'" @click="setArchived(o.order_id,true)"><Archive :size="14"/>归档订单</button></div></article></div>
<p v-if="!visibleOrders.length" class="orders-empty">{{orderFilter==='archived'?'暂无已归档订单。已完成订单可点击「归档订单」收进历史列表。':'暂无当前订单，可在「已归档」中查看历史订单并恢复。'}}</p></section>
 <DialogShell v-if="modal==='manual'" title="手动入库" :busy="busy" @close="modal=''"><div v-if="error" class="error-banner" role="alert">{{error}}</div><div class="segmented"><button :class="{active:manualKind==='new'}" @click="manualKind='new';manual.slot_id=''">新器件并入库</button><button :class="{active:manualKind==='existing'}" @click="manualKind='existing';manual.slot_id=''">已有器件补货</button></div><form @submit.prevent="manualSave"><div class="form-grid"><template v-if="manualKind==='new'"><label class="span2">名称 / 厂家型号<input v-model="manual.name" required maxlength="200" placeholder="例如 10 kΩ 或 AO3400A"></label><label>类别<select v-model="manual.category"><option v-for="c in categoryOptions" :key="c">{{c}}</option></select></label><label>封装<input v-model="manual.package" placeholder="0603 / SOT-23"></label><label>数值<input v-model="manual.value" placeholder="10k / 100nF"></label><label>商城编号<input v-model="manual.supplier_code" placeholder="选填，例如 C20917"></label><label v-for="key in specKeys" :key="key">{{key}}<input v-model="manual.specs[key]" :placeholder="({精度:'1%',功率:'0.1W',耐压:'25V',介质:'X7R',额定电流:'1A'} as Record<string,string>)[key]"></label></template><label v-else class="span2">选择已有器件<select v-model="manual.part_id" required @change="manual.slot_id=''"><option value="" disabled>请选择器件</option><option v-for="p in state.parts.filter(p=>!p.archived)" :value="p.id" :key="p.id">{{productName(p)}} · {{p.package}} · {{p.supplier_code}}</option></select></label><label class="span2">存放格子<select v-model="manual.slot_id" required><option value="" disabled>选择空格或同器件格子</option><option v-for="s in manualSlots" :value="s.id" :key="s.id">{{s.label}}</option></select></label><label>本次实物入库数量<input v-model.number="manual.quantity" type="number" min="1" step="1" required></label><label class="span2">来源 / 备注<input v-model="manual.note" placeholder="采购到货、散料整理或订单号"></label></div><p class="form-hint">数量会增加到所选格子。新格子记为精确数量；原有估算库存仍保留估算状态。</p><p v-if="!state.boxes.length" class="callout warm">请先到「元件与位置」创建收纳盒。</p><div class="modal-footer"><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy||!manual.slot_id">保存并入库</button></div></form></DialogShell>
 <DialogShell v-if="modal==='order'&&order" :title="order.update_existing?'更新立创采购订单':'导入立创采购订单'" wide :busy="busy" @close="modal=''"><div v-if="error" class="error-banner" role="alert">{{error}}</div><div v-if="order.update_existing" class="callout warm">正在更新已导入订单：相同商城编号更新原采购项，保留已验收数量和库存；新增物料等待验收。文件中缺少的旧明细会保留。商品名称与器件参数会同步更新档案。</div><p class="form-hint">{{order.filename}} · {{order.lines.length}} 项 · 合计 {{order.total_quantity}} 个。仅提取商品明细与订单号。</p><label class="order-id">订单号<input v-model="order.order_id" :disabled="order.update_existing" required maxlength="80"></label><div v-if="!order.update_existing" class="callout">确认后自动新建 / 复用器件档案，生成“待到货”采购记录。验收入库时再选择实际格子和数量。</div><p v-for="w in order.warnings" :key="w" class="warm-text">{{w}}</p><div class="table-wrap order-preview"><table><thead><tr><th class="row-number">序号</th><th>商城编号 / 商品名称</th><th>型号 / 封装</th><th>类别 / 数值</th><th>订购 / 发货</th><th>档案与检查</th></tr></thead><tbody><tr v-for="(line,index) in order.lines" :key="line.source_row"><td class="row-number">{{index+1}}</td><td><strong>{{line.supplier_code}}</strong><small>{{line.brand}}</small><textarea v-model="line.description" rows="2" :aria-label="line.supplier_code+' 商品名称'" placeholder="商品名称"></textarea><details><summary>关键参数</summary><label v-for="k in specKeys" :key="k">{{k}}<input v-model="line.specs[k]" :aria-label="line.supplier_code+' '+k"></label></details></td><td><input v-model="line.name" :aria-label="line.supplier_code+' 型号'"><input v-model="line.package" :aria-label="line.supplier_code+' 封装'"></td><td><select v-model="line.category" :aria-label="line.supplier_code+' 类别'"><option v-for="c in categoryOptions" :key="c">{{c}}</option><option v-if="!categoryOptions.includes(line.category)">{{line.category}}</option></select><input v-model="line.value" :aria-label="line.supplier_code+' 数值'" placeholder="数值（可选）"></td><td><input v-model="line.quantity" :aria-label="line.supplier_code+' 订购数量'" inputmode="numeric"><input v-model="line.shipped" :aria-label="line.supplier_code+' 发货数量'" inputmode="numeric" placeholder="未提供"></td><td><span class="badge" :class="line.reuse_id?'good':'neutral'">{{line.reuse_id?'复用档案':'新建档案'}}</span><small v-for="w in line.warnings" :key="w" class="warm-text">{{w}}</small><small v-for="e in line.errors" :key="e" class="red-text">{{e}}</small></td></tr></tbody></table></div><div class="modal-footer"><span v-if="order.errors" class="red-text">{{order.errors}} 行错误</span><span v-else-if="!ready" class="warm-text">内容已修改，请重新检查</span><button class="secondary" :disabled="busy" @click="preview">检查修改</button><button class="primary" :disabled="busy||!ready" @click="commit">{{order.update_existing?'保存订单更新':'确认导入采购订单'}}</button></div></DialogShell>
 <DialogShell v-if="modal==='receipt'" title="批量验收入库" wide :busy="busy" @close="modal=''"><div v-if="error" class="error-banner" role="alert">{{error}}</div><p>{{receiptTitle}}</p><p class="form-hint">只勾选已经收到并核对的实物。订单“发货数量”仅作为本次数量建议，可修改，支持部分验收。</p><div class="receipt-toolbar"><button class="secondary" @click="receiptRows.forEach(r=>r.selected=true)">全选待验收项</button><button class="text-button" @click="receiptRows.forEach(r=>r.selected=false)">取消全选</button><select v-model="allocationBox" aria-label="分配收纳盒"><option value="">自动按类别分配（根据盒名）</option><option v-for="b in state.boxes" :key="b.id" :value="b.id">{{b.code}} · {{b.name}}{{boxCategories(b).length?' · '+boxCategories(b).join(' / '):' · 未识别分类'}}</option></select><button class="secondary" :disabled="busy||!selectedReceipts.length" @click="allocate">{{allocationBox?'按顺序分配格子':'按类别分配格子'}}</button><button class="text-button" @click="selectedReceipts.forEach(r=>r.slot_id='')">清空所选位置</button></div><p class="form-hint">自动模式按盒名中的类别分配，例如“贴片电阻”“贴片电容”；优先同器件精确库存格，再按盒号和行列选择空格。已选位置保留，不同类别不会混放。分类未识别或格子不足时可手动选择。</p><p v-if="allocationMessage" class="callout" role="status">{{allocationMessage}}</p><div class="table-wrap order-preview"><table><thead><tr><th class="row-number">序号</th><th>验收</th><th>商品名称 / 型号</th><th>待入库 / 本次</th><th>放入格子</th></tr></thead><tbody><tr v-for="(r,index) in receiptRows" :key="r.purchase.id"><td class="row-number">{{index+1}}</td><td><input v-model="r.selected" type="checkbox" :aria-label="'验收 '+r.purchase.part_name"></td><td><strong>{{cleanProductName(r.purchase.product_name||r.purchase.part_name)}}</strong><small>{{r.purchase.part_name}}</small><small>{{r.purchase.package}} · {{r.purchase.order_id||'日常采购'}}</small></td><td><small>待入库 {{r.purchase.quantity-r.purchase.received}}</small><input v-model.number="r.quantity" type="number" min="1" :max="r.purchase.quantity-r.purchase.received" step="1" :aria-label="r.purchase.part_name+' 本次数量'"></td><td><select v-model="r.slot_id" :aria-label="r.purchase.part_name+' 存放格子'"><option value="">请选择位置</option><option v-for="s in slotsFor(r.purchase.part_id)" :key="s.id" :value="s.id">{{s.label}}</option></select><small v-if="r.selected&&!r.slot_id&&allocationReasons[r.purchase.id]" class="warm-text">{{allocationReasons[r.purchase.id]}}</small><small v-if="r.slot_id&&stockAt(r.slot_id)?.mode!=='exact'&&stockAt(r.slot_id)" class="warm-text">此格原为估算 / 未知数量，入库后仍需盘点</small></td></tr></tbody></table></div><div class="modal-footer"><span class="subtle">已选 {{selectedReceipts.length}} 项 · {{selectedReceipts.reduce((n,r)=>n+(Number(r.quantity)||0),0)}} 个</span><button class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy||!receiptsReady" @click="receive">确认验收入库</button></div></DialogShell>
 <ReceiptEditor v-if="correctionIds" :state="state" :ids="correctionIds" @close="correctionIds=null" @changed="corrected"/>
</template>
